card.classList.toggle('escuro');`}],desafios:[{tipo:"quiz",q:"document.querySelector('#placar') pega o quê?",opts:["Todos os elementos da classe placar",'O elemento com id="placar"',"A tag <placar>","O primeiro parágrafo da página"],correct:1,explain:"O querySelector usa a MESMA sintaxe dos seletores CSS: # é id, . é classe, sem nada é tag."},{tipo:"code",lang:"js",arquivo:"script.js",enunciado:"O clássico: botão contador, agora em JS puro.",contexto:"O HTML já está na página (olha o preview). Teu trabalho é só o JavaScript.",missao:"a cada clique no botão, o placar sobe: Cliques: 0 → Cliques: 1 → Cliques: 2...",testa:"👆 clica no botão do preview!",htmlBase:'<p id="placar">Cliques: 0</p><button id="botao">Clica aí</button>',starter:`// 1) pega o placar e o botao (id placar / id botao)
